<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../reports/filing_archive_service.php';$c=db();$failed=false;$missing=(int)$c->query("SELECT(SELECT COUNT(*) FROM erp_vat_periods p LEFT JOIN erp_filing_archives a ON a.declaration_type='VAT' AND a.source_entity_id=p.id AND a.user_id=p.user_id WHERE p.status='FILED' AND a.id IS NULL)+(SELECT COUNT(*) FROM erp_accounting_periods p LEFT JOIN erp_filing_archives a ON a.declaration_type='ACCOUNTING_PERIOD' AND a.source_entity_id=p.id AND a.user_id=p.user_id WHERE p.status='FILED' AND a.id IS NULL) n")->fetch_assoc()['n'];if($missing){$failed=true;fwrite(STDERR,"FAIL filed entities without archives: $missing\n");}else echo "PASS every filed entity has an archive\n";$bad=0;foreach($c->query('SELECT * FROM erp_filing_archives') as $r){$sh=hash('sha256',$r['source_json']);$rh=hash('sha256',$r['result_json']);$ah=hash('sha256',$r['report_version']."\n".$r['declaration_type']."\n".$r['source_entity_id']."\n".$sh."\n".$rh);if(!hash_equals($r['source_sha256'],$sh)||!hash_equals($r['result_sha256'],$rh)||!hash_equals($r['archive_sha256'],$ah))$bad++;}if($bad){$failed=true;fwrite(STDERR,"FAIL filing archive hashes: $bad mismatch(es)\n");}else echo "PASS filing archive hashes reconcile\n";exit($failed?1:0);
